DECLARE
  batch_size int := 5000;
  max_id bigint;
  cur_id bigint := 0;
BEGIN
  SELECT max(id) INTO max_id FROM orders;
  WHILE cur_id < max_id LOOP
    UPDATE orders
    SET total_cents_new = total_cents
    WHERE id > cur_id AND id <= cur_id + batch_size
      AND total_cents_new IS NULL;
    cur_id := cur_id + batch_size;
    COMMIT;
  END LOOP;
END $$;

-- Step 3: add a trigger to keep new column in sync for concurrent writes during backfill
-- (should be created before backfill in production; included here for completeness)
CREATE OR REPLACE FUNCTION sync_total_cents_new() RETURNS trigger AS $$
BEGIN
  NEW.total_cents_new := NEW.total_cents;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_total_cents_new
BEFORE INSERT OR UPDATE ON orders
FOR EACH ROW EXECUTE FUNCTION sync_total_cents_new();

